# Temperature Converter: Celsius to Fahrenheit

Here's a complete Java program that converts temperature from Celsius to Fahrenheit:

## Method 1: Basic Console Input Version

```java
import java.util.Scanner;

public class TemperatureConverter {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.println("=== Celsius to Fahrenheit Converter ===");
        System.out.print("Enter temperature in Celsius: ");

        double celsius = scanner.nextDouble();
        double fahrenheit = celsiusToFahrenheit(celsius);

        System.out.printf("%.2f°C = %.2f°F%n", celsius, fahrenheit);

        scanner.close();
    }

    /**
     * Converts Celsius to Fahrenheit
     * Formula: F = (C × 9/5) + 32
     */
    public static double celsiusToFahrenheit(double celsius) {
        return (celsius * 9.0 / 5.0) + 32;
    }
}
```

## Method 2: Enhanced Version with Input Validation

```java
import java.util.Scanner;

public class TemperatureConverterEnhanced {
    // Absolute zero in Celsius
    private static final double ABSOLUTE_ZERO = -273.15;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.println("=== Celsius to Fahrenheit Converter ===");

        while (true) {
            System.out.print("Enter temperature in Celsius (or 'q' to quit): ");

            if (scanner.hasNext("q") || scanner.hasNext("Q")) {
                System.out.println("Goodbye!");
                break;
            }

            if (scanner.hasNextDouble()) {
                double celsius = scanner.nextDouble();

                if (celsius < ABSOLUTE_ZERO) {
                    System.out.printf("Error: Temperature cannot be below absolute zero (%.2f°C)%n", 
                                    ABSOLUTE_ZERO);
                } else {
                    double fahrenheit = celsiusToFahrenheit(celsius);
                    System.out.printf("%.2f°C = %.2f°F%n", celsius, fahrenheit);
                    displayTemperatureInfo(celsius);
                }
            } else {
                System.out.println("Invalid input! Please enter a numeric value.");
                scanner.next(); // Clear invalid input
            }

            System.out.println();
        }

        scanner.close();
    }

    /**
     * Converts Celsius to Fahrenheit
     * Formula: F = (C × 9/5) + 32
     */
    public static double celsiusToFahrenheit(double celsius) {
        return (celsius * 9.0 / 5.0) + 32;
    }

    /**
     * Displays additional temperature information
     */
    public static void displayTemperatureInfo(double celsius) {
        if (celsius == 0) {
            System.out.println("Info: This is the freezing point of water.");
        } else if (celsius == 100) {
            System.out.println("Info: This is the boiling point of water.");
        } else if (celsius < 0) {
            System.out.println("Info: Below freezing point.");
        } else if (celsius > 100) {
            System.out.println("Info: Above boiling point.");
        } else if (celsius >= 20 && celsius <= 25) {
            System.out.println("Info: Comfortable room temperature.");
        }
    }
}
```

